//! `cargo xtask render`: `platform/STRATA-2027.md` from the spec.

use std::fmt::Write as _;

use crate::spec::{Reference, Source, Spec};

pub const OUTPUT: &str = "platform/STRATA-2027.md";

fn or_dash(s: &str) -> &str {
    if s.is_empty() { "—" } else { s }
}

pub fn render(spec: &Spec) -> String {
    let mut o = String::new();
    let pf = &spec.platform;
    let year = pf.year;
    let cy = &pf.vfx_reference_platform;

    // `write!` to a String cannot fail.
    let _ = writeln!(
        o,
        "<!-- Generated by `cargo xtask render` from platform/strata-{year}.toml. Do not edit. -->"
    );
    let _ = writeln!(o);
    let _ = writeln!(o, "# {} {year}", pf.name);
    let _ = writeln!(o);
    let _ = writeln!(
        o,
        "**Status:** {} · **Facade:** `{}` {} (lib `{}`) · **Tracks:** VFX Reference Platform {cy}",
        pf.status, pf.facade_package, pf.version, pf.facade_lib
    );
    let _ = writeln!(o);
    let _ = writeln!(
        o,
        "The {} {year} platform pins the shared vocabulary crates and the pure-Rust ports of the \
         VFX libraries (\"minerals\") so that every crate built on {} {year} shares one version of \
         each. Version ranges are Cargo caret ranges. Anything built against {} {year} should \
         resolve to versions inside every range below.",
        pf.name, pf.name, pf.name
    );
    let _ = writeln!(o);

    let _ = writeln!(o, "## Rust");
    let _ = writeln!(o);
    let _ = writeln!(o, "| Component | {} {year} |", pf.name);
    let _ = writeln!(o, "|---|---|");
    let _ = writeln!(o, "| Toolchain (CI) | {} |", spec.rust.toolchain);
    let _ = writeln!(o, "| Minimum supported Rust version | {} |", spec.rust.msrv);
    let _ = writeln!(o, "| Edition (Strata crates) | {} |", spec.rust.edition);
    let _ = writeln!(o);

    let _ = writeln!(o, "## Vocabulary crates");
    let _ = writeln!(o);
    let _ = writeln!(o, "Exactly one version of each is allowed in a conformant graph.");
    let _ = writeln!(o);
    let _ = writeln!(o, "| Crate | {} {year} | Features | Why it is shared |", pf.name);
    let _ = writeln!(o, "|---|---|---|---|");
    for (name, v) in &spec.vocabulary {
        let features = if v.features.is_empty() {
            "—".to_owned()
        } else {
            v.features
                .iter()
                .map(|f| format!("`{f}`"))
                .collect::<Vec<_>>()
                .join(", ")
        };
        let _ = writeln!(o, "| `{name}` | {} | {features} | {} |", v.version, v.why);
    }
    let _ = writeln!(o);

    let _ = writeln!(o, "## Minerals");
    let _ = writeln!(o);
    let _ = writeln!(
        o,
        "| Mineral (feature) | Package | {} {year} | Source | C++ library | {cy} | Validated against | Reference status |",
        pf.name
    );
    let _ = writeln!(o, "|---|---|---|---|---|---|---|---|");
    for (key, m) in &spec.minerals {
        let source = match m.source {
            Source::CratesIo => "crates.io".to_owned(),
            Source::Git => format!(
                "git `{}` (blocks publishing)",
                short(m.rev.as_deref().unwrap_or_default())
            ),
        };
        let mut packages = m.packages().map(|p| format!("`{p}`")).collect::<Vec<_>>().join(", ");
        if m.lib.replace('_', "-") != m.package {
            let _ = write!(packages, " (lib `{}`)", m.lib);
        }
        let target = if m.on_vfx_platform {
            or_dash(&m.cpp_target).to_owned()
        } else if m.cpp_target.is_empty() {
            "not on the list".to_owned()
        } else {
            format!("not on the list (target {})", m.cpp_target)
        };
        let status = match m.reference() {
            Reference::Matches => "matches",
            Reference::Lagging => "lagging",
            Reference::Undeclared => "undeclared",
        };
        let _ = writeln!(
            o,
            "| `{key}` | {packages} | {} | {source} | {} | {target} | {} | {status} |",
            m.version,
            m.cpp_library,
            or_dash(&m.cpp_validated),
        );
    }
    let _ = writeln!(o);

    let _ = writeln!(o, "## Watched crates");
    let _ = writeln!(o);
    let _ = writeln!(
        o,
        "Private to the minerals today, so duplicates are tolerated. A crate moves to the \
         vocabulary list once a mineral exposes one of its types."
    );
    let _ = writeln!(o);
    let _ = writeln!(o, "| Crate | {} {year} |", pf.name);
    let _ = writeln!(o, "|---|---|");
    for (name, v) in &spec.watched {
        let _ = writeln!(o, "| `{name}` | {v} |");
    }
    let _ = writeln!(o);

    let _ = writeln!(o, "## Reference consumers");
    let _ = writeln!(o);
    let _ = writeln!(o, "Built by `strata-check` against the platform in every CI run.");
    let _ = writeln!(o);
    let _ = writeln!(o, "| Consumer | Repository | Revision | Packages |");
    let _ = writeln!(o, "|---|---|---|---|");
    for (name, c) in &spec.consumers {
        let packages = c
            .packages
            .iter()
            .map(|p| format!("`{p}`"))
            .collect::<Vec<_>>()
            .join(", ");
        let _ = writeln!(o, "| {name} | <{}> | `{}` | {packages} |", c.repository, short(&c.rev));
    }
    let _ = writeln!(o);

    let _ = writeln!(o, "## Blocking items");
    let _ = writeln!(o);
    let mut any = false;
    for (key, m) in &spec.minerals {
        for b in &m.blocking {
            any = true;
            let _ = writeln!(o, "- **{key}**: {b}");
        }
    }
    for (name, c) in &spec.consumers {
        for b in &c.blocking {
            any = true;
            let _ = writeln!(o, "- **{name}**: {b}");
        }
    }
    if !any {
        let _ = writeln!(o, "None.");
    }
    let _ = writeln!(o);

    if !spec.patches.is_empty() || spec.minerals.values().any(|m| m.patch.is_some()) {
        let _ = writeln!(o, "## Workspace patches (strata-check only)");
        let _ = writeln!(o);
        let _ = writeln!(
            o,
            "These apply to the Strata workspace, never to users of the published facade."
        );
        let _ = writeln!(o);
        for (key, m) in &spec.minerals {
            if let Some(p) = &m.patch {
                let _ = writeln!(o, "- `{key}` → {} at `{}`", p.git, short(&p.rev));
            }
        }
        for p in &spec.patches {
            let _ = writeln!(
                o,
                "- `{}` from {} → crates.io {}: {}",
                p.package, p.source, p.version, p.why
            );
        }
        let _ = writeln!(o);
    }
    o
}

fn short(rev: &str) -> &str {
    rev.get(..7).unwrap_or(rev)
}
